mapper.select:
select t.id::text id,t.display_snapshot->>'title' title, t.display_snapshot->>'knowledgePoint' knowledge_point, coalesce((question_item.target_data->>'questionCount')::int,0) question_count, coalesce(progress.submitted_count,0) completed_question_count, t.estimated_minutes, greatest(t.update_time,coalesce(progress.attempt_updated,t.update_time), coalesce(progress.session_updated,t.update_time),coalesce(progress.question_updated,t.update_time)) updated_at, t.display_snapshot->>'recommendation' recommendation, case when progress.session_id is null and not progress.has_attempt then 'START' else 'CONTINUE' end action from cm_learning_task t join cm_task_item question_item on question_item.task_id=t.id and question_item.item_order=2 and question_item.item_type='question' left join lateral ( select (select max(s.id) from cm_learning_session s where s.source_task_id=t.id and s.user_id=#{userId} and s.goal_id=#{goalId} and s.session_type='daily_task') session_id, exists(select 1 from cm_task_item ti join cm_task_attempt ta on ta.task_item_id=ti.id where ti.task_id=t.id) has_attempt, (select count(distinct qa.id)::int from cm_learning_session s join cm_session_question sq on sq.session_id=s.id join cm_question_attempt qa on qa.session_question_id=sq.id and qa.user_id=#{userId} where s.source_task_id=t.id and s.session_type='daily_task' and qa.status='submitted') submitted_count, (select max(a.completed_time) from cm_task_item ti join cm_task_attempt a on a.task_item_id=ti.id where ti.task_id=t.id) attempt_updated, (select max(s.update_time) from cm_learning_session s where s.source_task_id=t.id and s.session_type='daily_task') session_updated, (select max(qa.update_time) from cm_learning_session s join cm_session_question sq on sq.session_id=s.id join cm_question_attempt qa on qa.session_question_id=sq.id where s.source_task_id=t.id) question_updated ) progress on true where t.user_id=#{userId} and t.goal_id=#{goalId} and
and (t.display_snapshot->>'title' ilike concat('%',#{keyword},'%') or t.display_snapshot->>'knowledgePoint' ilike concat('%',#{keyword},'%'))
order by t.create_time,t.id offset #{offset} limit #{limit}
